import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
} from "react";

import api from "../lib/api";

const Ctx = createContext(null);

export const useAuth = () => useContext(Ctx);

const emptyState = {
  loading: true,
  user: null,
  business: null,
  permissions: [],

  subscriptionLoading: true,
  subscriptionRequired: false,
  subscriptionStatus: null,
  hasSubscriptionAccess: false,

  // 7-day trial information
  accessType: null,
  trialActive: false,
  trialDaysRemaining: null,
  trialStartedAt: null,
  trialExpiresAt: null,
};

export function AuthProvider({ children }) {
  const [state, setState] = useState(emptyState);

  const load = useCallback(async () => {
    const token = localStorage.getItem("token");

    if (!token) {
      setState({
        ...emptyState,
        loading: false,
        subscriptionLoading: false,
      });
      return;
    }

    try {
      const { data } = await api.get("/auth/me");

      let subscriptionRequired = false;
      let subscriptionStatus = null;
      let hasSubscriptionAccess = false;

      let accessType = null;
      let trialActive = false;
      let trialDaysRemaining = null;
      let trialStartedAt = null;
      let trialExpiresAt = null;

      // Owner is permanently exempt.
      if (data.user?.role === "owner") {
        subscriptionRequired = false;
        subscriptionStatus = "exempt";
        hasSubscriptionAccess = true;
        accessType = "owner";
      } else {
        try {
          const subscriptionResponse = await api.get(
            "/subscription/status"
          );

          const subscription =
            subscriptionResponse.data || {};

          subscriptionRequired =
            subscription.subscription_required ?? true;

          subscriptionStatus =
            subscription.subscription_status ?? "inactive";

          // This is intentionally named hasSubscriptionAccess for
          // compatibility with the rest of the existing app. It means
          // "allowed to use the app", whether by trial or paid subscription.
          hasSubscriptionAccess =
            subscription.has_access === true;

          accessType =
            subscription.access_type ?? null;

          trialActive =
            subscription.trial_active === true;

          trialDaysRemaining =
            subscription.trial_days_remaining ?? null;

          trialStartedAt =
            subscription.trial_started_at ?? null;

          trialExpiresAt =
            subscription.trial_expires_at ?? null;
        } catch (subscriptionError) {
          console.error(
            "Unable to check subscription/trial:",
            subscriptionError
          );

          // Fail closed for non-owner users.
          subscriptionRequired = true;
          subscriptionStatus = "unknown";
          hasSubscriptionAccess = false;
          accessType = "unknown";
          trialActive = false;
          trialDaysRemaining = null;
          trialStartedAt = null;
          trialExpiresAt = null;
        }
      }

      setState({
        loading: false,
        user: data.user,
        business: data.business,
        permissions: data.permissions || [],

        subscriptionLoading: false,
        subscriptionRequired,
        subscriptionStatus,
        hasSubscriptionAccess,

        accessType,
        trialActive,
        trialDaysRemaining,
        trialStartedAt,
        trialExpiresAt,
      });
    } catch (error) {
      console.error("Authentication load failed:", error);

      localStorage.removeItem("token");

      setState({
        ...emptyState,
        loading: false,
        subscriptionLoading: false,
      });
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  // Login
  const login = async (email, password) => {
    const { data } = await api.post("/auth/login", {
      email,
      password,
    });

    localStorage.setItem("token", data.token);

    await load();

    return data;
  };

  // Register
  const register = async (name, email, password) => {
    const { data } = await api.post("/auth/register", {
      name,
      email,
      password,
    });

    localStorage.setItem("token", data.token);

    await load();

    return data;
  };

  // Business setup
  const setupBusiness = async (payload) => {
    const { data } = await api.post("/business", payload);

    localStorage.setItem("token", data.token);

    await load();

    return data;
  };

  // Refresh trial/subscription status after payment or other changes.
  const refreshSubscription = async () => {
    await load();
  };

  // Logout
  const logout = () => {
    localStorage.removeItem("token");

    setState({
      ...emptyState,
      loading: false,
      subscriptionLoading: false,
    });
  };

  // Permission check
  const can = (module) =>
    state.permissions.includes("*") ||
    state.permissions.includes(module);

  return (
    <Ctx.Provider
      value={{
        ...state,
        login,
        register,
        setupBusiness,
        logout,
        can,
        reload: load,
        refreshSubscription,
      }}
    >
      {children}
    </Ctx.Provider>
  );
}
