import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api, { apiError } from '../lib/api';
import { inr } from '../lib/format';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from './ui/dialog';
import { toast } from 'sonner';

const TYPES = {sales:'Sales / bills',purchases:'Purchases','sales-returns':'Sales returns','purchase-returns':'Supplier returns',batches:'Stock batches / expiry',products:'Products',customers:'Customers',suppliers:'Suppliers',payments:'Payment receipts',expenses:'Expenses'};
const fields = {
 products:[['name','Medicine name'],['strength','Strength'],['manufacturer','Manufacturer'],['brand','Brand'],['generic','Generic'],['composition','Composition'],['category','Category'],['hsn','HSN'],['pack_size','Pack size'],['unit','Stock unit'],['mrp','MRP','number'],['purchase_rate','Purchase rate','number'],['selling_rate','Selling rate','number'],['gst_rate','GST %','number'],['min_stock','Minimum stock','number'],['reorder_level','Reorder level','number']],
 customers:[['name','Name'],['phone','Phone'],['email','Email'],['address','Address'],['gstin','GSTIN'],['credit_limit','Credit limit','number'],['opening_balance','Opening balance','number'],['notes','Notes']],
 suppliers:[['name','Name'],['contact_person','Contact person'],['phone','Phone'],['email','Email'],['address','Address'],['gstin','GSTIN'],['drug_license','Drug licence'],['payment_terms','Payment terms'],['opening_balance','Opening balance','number'],['notes','Notes']],
 batches:[['batch_number','Batch number'],['expiry_date','Verified expiry date','date'],['available_qty','Available quantity','number'],['mrp','MRP per stock unit','number'],['selling_price','Selling price per stock unit','number']],
 expenses:[['date','Date','date'],['category','Category'],['amount','Amount','number'],['method','Payment method'],['description','Description']],
 payments:[['date','Date','date'],['amount','Amount','number'],['method','Payment method'],['note','Note']],
 'purchase-returns':[['qty','Quantity to return','number'],['reason','Return reason']],
 'sales-returns':[['reason','Return reason']]
};
const endpoint = (kind,id) => kind==='batches' ? `/inventory/batches/${id}` : `/${kind}/${id}`;
const title = r => r.name || r.invoice_no || r.purchase_no || r.return_no || r.product_name || r.reference || r.category || r.id;
export function ChangeReason({value,onChange}) { return <label className="block text-sm my-3">Reason for this change *<Input aria-label="Reason for this change" value={value || ''} onChange={e=>onChange(e.target.value)} placeholder="Describe the correction" /></label>; }

export default function RecordTools({types=Object.keys(TYPES),onChanged,derived=false}) {
 const navigate=useNavigate();
 const [open,setOpen]=useState(false),[kind,setKind]=useState(types[0]),[search,setSearch]=useState(''),[skip,setSkip]=useState(0);
 const [data,setData]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[reload,setReload]=useState(0);
 const [edit,setEdit]=useState(null),[removing,setRemoving]=useState(false),[why,setWhy]=useState('');
 useEffect(()=>{
  if(!open)return; let active=true;setData(null);setError('');
  const timer=setTimeout(()=>api.get(`/records/${kind}`,{params:{search,skip,limit:50}}).then(r=>{if(active)setData(r.data);}).catch(e=>{if(active)setError(apiError(e));}),200);
  return()=>{active=false;clearTimeout(timer);};
 },[open,kind,search,skip,reload]);
 const begin=async(record,del=false)=>{
  if(!del && kind==='sales'){setOpen(false);navigate(`/pos?edit=${record.id}`);return;}
  if(!del && kind==='purchases'){setOpen(false);navigate(`/purchases?edit=${record.id}`);return;}
  setBusy(true);setError('');
  try {
   let form={...record};
   if(kind==='sales-returns' && !del){const {data:sale}=await api.get(`/sales/${record.sale_id}`);form.items=sale.items.map(i=>({...i,sale_item_id:i.id,qty:record.items.find(r=>r.sale_item_id===i.id)?.qty || 0}));}
   setEdit(form);setRemoving(del);setWhy('');
  } catch(e){setError(apiError(e));}finally{setBusy(false);}
 };
 const save=async()=>{
  if(!why.trim())return setError('Enter a reason for the change.');
  setBusy(true);setError('');
  try {
   const payload={...edit,expected_revision:edit.revision || 0,change_reason:why};
   if(kind==='sales-returns')payload.items=edit.items.filter(i=>Number(i.qty)>0).map(i=>({sale_item_id:i.sale_item_id,qty:Number(i.qty)}));
   if(removing)await api.delete(kind==='products'?`/records/products/${edit.id}`:endpoint(kind,edit.id),{data:payload});
   else await api.put(endpoint(kind,edit.id),payload);
   toast.success(removing?'Record deleted; linked totals updated':'Changes saved; linked totals updated');
   setEdit(null);setReload(v=>v+1);if(onChanged)onChanged();
  }catch(e){setError(apiError(e));}finally{setBusy(false);}
 };
 const change=(key,value)=>setEdit(v=>({...v,[key]:value}));
 return <div className="flex flex-wrap items-center gap-3 mb-4">
  <Button variant="outline" data-testid="record-tools" onClick={()=>{setOpen(true);setEdit(null);setReload(v=>v+1);}}>Edit / delete records</Button>
  {derived && <span className="text-xs text-muted-foreground">Totals recalculate from the invoices, returns, payments and expenses you correct.</span>}
  <Dialog open={open} onOpenChange={v=>{if(!busy){setOpen(v);if(!v && onChanged)onChanged();}}}>
   <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
    <DialogHeader><DialogTitle>{edit ? `${removing?'Delete':'Edit'} · ${title(edit)}`:'Edit / delete records'}</DialogTitle></DialogHeader>
    {error && <p role="alert" className="border border-red-400 text-red-700 p-3 rounded">{error}</p>}
    {edit ? <fieldset disabled={busy} className="space-y-3">
     {removing ? <div className="bg-amber-50 text-amber-950 p-3 rounded text-sm">Delete this record? Linked stock and account entries will be reversed where applicable. Change history is retained. If stock has been used or an account still has a balance, resolve that first.</div> : <>
      <div className="grid sm:grid-cols-2 gap-3">{(fields[kind] || []).map(([key,label,type='text'])=><label key={key} className="text-sm">{label}<Input type={type} step={type==='number'?'any':undefined} value={edit[key] ?? ''} onChange={e=>change(key,type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value)} /></label>)}</div>
      {kind==='batches' && <p className="text-sm text-amber-700">Check expiry against the physical pack or supplier bill. Changing available quantity also records a stock adjustment.</p>}
      {['customers','suppliers'].includes(kind) && <p className="text-sm">Current balance: {inr(edit.balance)}. Opening-balance corrections create a matching ledger entry. Correct other balances through invoices, returns or receipts.</p>}
      {kind==='payments' && <p className="text-sm">Receipt {edit.reference}. The account remains unchanged. Invoice payments must be corrected in the original invoice.</p>}
      {kind==='products' && <label className="text-sm flex gap-2"><input type="checkbox" checked={edit.active!==false} onChange={e=>change('active',e.target.checked)} />Active product</label>}
      {kind==='sales-returns' && <><label className="text-sm flex gap-2"><input type="checkbox" checked={Boolean(edit.restock)} onChange={e=>change('restock',e.target.checked)} />Restock returned items</label>{edit.items.map((it,i)=><label key={it.sale_item_id} className="block text-sm">{it.product_name} · {it.batch_number} — return quantity<Input type="number" min="0" step="any" value={it.qty} onChange={e=>change('items',edit.items.map((x,n)=>i===n?{...x,qty:e.target.value}:x))}/></label>)}</>}
     </>}
     <ChangeReason value={why} onChange={setWhy}/>
     <div className="flex gap-2"><Button variant="outline" onClick={()=>{setEdit(null);setError('');}}>Back</Button><Button variant={removing?'destructive':'default'} disabled={busy || !why.trim()} onClick={save}>{busy?'Saving…':removing?'Confirm deletion':'Save changes'}</Button></div>
    </fieldset> : <>
     <div className="flex flex-wrap gap-2"><select aria-label="Record type" className="border rounded p-2 bg-background" value={kind} onChange={e=>{setKind(e.target.value);setSkip(0);setSearch('');}}>{types.map(t=><option key={t} value={t}>{TYPES[t]}</option>)}</select><Input className="max-w-xs" aria-label="Find record" placeholder="Search name, invoice or batch" value={search} onChange={e=>{setSearch(e.target.value);setSkip(0);}}/></div>
     {kind==='payments' && <p className="text-sm">Standalone receipts only. To change an invoice payment, edit the sale or purchase.</p>}
     {!data ? <p>{error?'Unable to load records.':'Loading records…'}</p> : <><div className="overflow-auto"><table className="w-full text-sm"><thead><tr className="text-left"><th className="p-2">Record</th><th className="p-2">Date / detail</th><th className="p-2">Value / quantity</th><th className="p-2">Actions</th></tr></thead><tbody>{data.items.map(r=><tr key={r.id} className="border-t"><td className="p-2">{title(r)}<div className="text-xs text-muted-foreground">{r.supplier_name || r.customer_name || r.batch_number}</div></td><td className="p-2">{r.expiry_date || r.invoice_date || r.date || '—'}</td><td className="p-2">{kind==='batches'?`${r.available_qty} units`:inr(r.grand_total ?? r.refund_amount ?? r.value ?? r.amount ?? r.balance ?? r.mrp ?? 0)}</td><td className="p-2 whitespace-nowrap"><Button size="sm" variant="ghost" onClick={()=>begin(r)} disabled={busy}>Edit</Button><Button size="sm" variant="ghost" className="text-red-600" onClick={()=>begin(r,true)} disabled={busy}>Delete</Button></td></tr>)}</tbody></table>{!data.items.length && <p className="p-3">No matching records.</p>}</div><div className="flex items-center gap-3 text-sm"><Button size="sm" variant="outline" disabled={!skip} onClick={()=>setSkip(v=>Math.max(0,v-50))}>Previous</Button><span>{data.total?skip+1:0}–{Math.min(skip+50,data.total)} of {data.total}</span><Button size="sm" variant="outline" disabled={skip+50>=data.total} onClick={()=>setSkip(v=>v+50)}>Next</Button></div></>}
    </>}
   </DialogContent>
  </Dialog>
 </div>;
}
