import "@/App.css";
import {
  BrowserRouter,
  Routes,
  Route,
  Navigate,
  useLocation,
} from "react-router-dom";

import { Toaster } from "@/components/ui/sonner";
import { AuthProvider, useAuth } from "@/context/AuthContext";
import Layout from "@/components/Layout";
import { Loading } from "@/components/common";

import Login from "@/pages/Login";
import Setup from "@/pages/Setup";
import Subscription from "@/pages/Subscription";

import Dashboard from "@/pages/Dashboard";
import POS from "@/pages/POS";
import Sales from "@/pages/Sales";
import Purchases from "@/pages/Purchases";
import Inventory from "@/pages/Inventory";
import Products from "@/pages/Products";
import Expiry from "@/pages/Expiry";
import Customers from "@/pages/Customers";
import Suppliers from "@/pages/Suppliers";
import UdharKhata from "@/pages/UdharKhata";
import Expenses from "@/pages/Expenses";
import Reports from "@/pages/Reports";
import Settings from "@/pages/Settings";
import AdminPortal from "@/pages/AdminPortal";


/* ------------------------------------------------------------------
   Authentication + Subscription Protection
------------------------------------------------------------------ */

function Protected({ children, allowSubscriptionPage = false }) {
  const {
    loading,
    subscriptionLoading,
    user,
    business,
    hasSubscriptionAccess,
  } = useAuth();

  const location = useLocation();

  if (loading || subscriptionLoading) {
    return (
      <div className="min-h-screen grid place-items-center">
        <Loading />
      </div>
    );
  }

  /* Not logged in */
  if (!user) {
    return <Navigate to="/login" replace />;
  }

  /*
   * Owner always has access.
   * Non-owner must have an active subscription.
   */
  const isOwner = user.role === "owner";

  if (
    !isOwner &&
    !hasSubscriptionAccess &&
    !allowSubscriptionPage
  ) {
    return <Navigate to="/subscription" replace />;
  }

  /*
   * If payment is already active, don't leave the user
   * sitting on the subscription page.
   */
  if (
    allowSubscriptionPage &&
    (isOwner || hasSubscriptionAccess)
  ) {
    return <Navigate to="/" replace />;
  }

  /*
   * Business setup is checked only after subscription access.
   */
  if (
    !business &&
    location.pathname !== "/setup" &&
    location.pathname !== "/subscription"
  ) {
    return <Navigate to="/setup" replace />;
  }

  return children;
}


/* ------------------------------------------------------------------
   Normal MediStock pages
------------------------------------------------------------------ */

function Shell({ module, children }) {
  const { can } = useAuth();

  return (
    <Protected>
      {module && !can(module) ? (
        <Navigate to="/" replace />
      ) : (
        <Layout>{children}</Layout>
      )}
    </Protected>
  );
}


/* ------------------------------------------------------------------
   Application
------------------------------------------------------------------ */

function App() {
  return (
    <div className="App">
      <AuthProvider>
        <BrowserRouter basename={process.env.PUBLIC_URL || "/"}>
          <Routes>

            {/* Login */}
            <Route
              path="/login"
              element={<Login />}
            />

            {/* ₹200/month subscription */}
            <Route
              path="/subscription"
              element={
                <Protected allowSubscriptionPage>
                  <Subscription />
                </Protected>
              }
            />

            {/* Business setup */}
            <Route
              path="/setup"
              element={
                <Protected>
                  <Setup />
                </Protected>
              }
            />

            {/* Dashboard */}
            <Route
              path="/"
              element={
                <Shell module="dashboard">
                  <Dashboard />
                </Shell>
              }
            />

            {/* POS */}
            <Route
              path="/pos"
              element={
                <Shell module="pos">
                  <POS />
                </Shell>
              }
            />

            {/* Sales */}
            <Route
              path="/sales"
              element={
                <Shell module="sales">
                  <Sales />
                </Shell>
              }
            />

            {/* Purchases */}
            <Route
              path="/purchases"
              element={
                <Shell module="purchases">
                  <Purchases />
                </Shell>
              }
            />

            {/* Inventory */}
            <Route
              path="/inventory"
              element={
                <Shell module="inventory">
                  <Inventory />
                </Shell>
              }
            />

            {/* Products */}
            <Route
              path="/products"
              element={
                <Shell module="products">
                  <Products />
                </Shell>
              }
            />

            {/* Expiry */}
            <Route
              path="/expiry"
              element={
                <Shell module="expiry">
                  <Expiry />
                </Shell>
              }
            />

            {/* Customers */}
            <Route
              path="/customers"
              element={
                <Shell module="customers">
                  <Customers />
                </Shell>
              }
            />

            {/* Suppliers */}
            <Route
              path="/suppliers"
              element={
                <Shell module="suppliers">
                  <Suppliers />
                </Shell>
              }
            />

            {/* Udhar Khata */}
            <Route
              path="/udhar"
              element={
                <Shell module="udhar">
                  <UdharKhata />
                </Shell>
              }
            />

            {/* Expenses */}
            <Route
              path="/expenses"
              element={
                <Shell module="expenses">
                  <Expenses />
                </Shell>
              }
            />

            {/* Reports */}
            <Route
              path="/reports"
              element={
                <Shell module="reports">
                  <Reports />
                </Shell>
              }
            />

            {/* Admin */}
            <Route
              path="/admin"
              element={
                <Shell module="settings">
                  <AdminPortal />
                </Shell>
              }
            />

            {/* Settings */}
            <Route
              path="/settings"
              element={
                <Shell module="settings">
                  <Settings />
                </Shell>
              }
            />

            {/* Unknown URL */}
            <Route
              path="*"
              element={<Navigate to="/" replace />}
            />

          </Routes>
        </BrowserRouter>

        <Toaster position="top-right" richColors />
      </AuthProvider>
    </div>
  );
}

export default App;
